listen_acoustic:
import math
values = []
for item in items:
    raw = item.get('mood_acoustic', None, with_album=False)
    if raw is None or raw == "":
        continue
    try:
        value = float(raw)
    except (TypeError, ValueError):
        continue
    if math.isfinite(value) and 0 <= value <= 1:
        values.append(value)
return sum(values) / len(values) if values else None

