listen_rosamerica:
import unicodedata
values = []
for item in items:
    raw = item.get("genre_rosamerica", None, with_album=False)
    if not raw:
        continue
    value = " ".join("".join(c for c in unicodedata.normalize("NFKD", str(raw).casefold()) if not unicodedata.combining(c)).split())
    if value:
        values.append(value)
return min(set(values), key=lambda value: (-values.count(value), value)) if values else None

